def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    my_c = 0
    for my, opp in history:
        if my == 'C':
            my_c += 1
        if opp == 'C':
            opp_c += 1

    my_d = n - my_c
    opp_d = n - opp_c

    if opp_c == 0:
        return 'D'

    if n <= 2:
        return 'C' if opp_last == 'C' else 'D'

    start = 0 if n <= 12 else n - 12
    recent = history[start:n]
    recent_len = len(recent)
    recent_opp_c = sum(1 for _, o in recent if o == 'C')
    recent_my_c = sum(1 for m, _ in recent if m == 'C')

    opp_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            opp_streak += 1
        else:
            break

    if opp_c * 100 < n * 50:
        if recent_opp_c >= 8 and opp_last == 'C':
            return 'C'
        if recent_opp_c <= 2:
            return 'D' if rng.random() < 0.90 else 'C'
        if opp_last == 'D':
            return 'D'
        return 'D' if rng.random() < 0.55 else 'C'

    if opp_c == n and my_c == n:
        if 88 <= n <= 94 and rng.random() < 0.02:
            return 'D'
        return 'C'

    punished = 0
    forgiven = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'D':
                punished += 1
            else:
                forgiven += 1

    retaliatory = my_d >= 2 and punished * 100 >= my_d * 70
    forgiving = my_d >= 1 and forgiven * 100 >= my_d * 75 and opp_c * 100 >= n * 65
    if retaliatory:
        forgiving = False

    if opp_last == 'D':
        if n >= 97:
            return 'D'

        if my_last == 'D':
            if opp_streak >= 4:
                return 'D'
            if opp_c * 100 >= n * 55 and recent_opp_c >= 4:
                if recent_opp_c >= 7 or opp_c * 100 >= n * 75:
                    return 'C' if rng.random() < 0.85 else 'D'
                return 'C' if rng.random() < 0.65 else 'D'
            if opp_c * 100 >= n * 35 and recent_opp_c >= 7:
                return 'C' if rng.random() < 0.50 else 'D'
            return 'D'

        prev_my = history[-2][0]
        prev_opp = history[-2][1]

        if prev_my == 'D' and prev_opp == 'C':
            if opp_c * 100 >= n * 65 and recent_opp_c >= 6:
                return 'C' if rng.random() < 0.70 else 'D'
            return 'D'

        if opp_streak >= 2:
            return 'D'

        if recent_opp_c >= 10 and opp_c * 100 >= n * 80:
            return 'C' if rng.random() < 0.40 else 'D'

        if recent_opp_c >= 7 and opp_c * 100 >= n * 70:
            return 'C' if rng.random() < 0.20 else 'D'

        return 'D'

    if my_last == 'D':
        if forgiving:
            if n >= 90:
                return 'D' if rng.random() < 0.60 else 'C'
            if n >= 70:
                return 'D' if rng.random() < 0.40 else 'C'
            return 'D' if rng.random() < 0.25 else 'C'

        if recent_opp_c >= 5 and opp_c * 100 >= n * 50:
            return 'C'

        return 'D' if rng.random() < 0.20 else 'C'

    if forgiving and opp_c * 100 >= n * 75 and recent_opp_c == recent_len and recent_my_c == recent_len:
        if n >= 90:
            if rng.random() < 0.30:
                return 'D'
        elif n >= 60:
            if rng.random() < 0.15:
                return 'D'
        elif n >= 30:
            if rng.random() < 0.07:
                return 'D'

    if forgiving and opp_c * 100 >= n * 70 and n >= 96:
        return 'D'

    if opp_c * 100 < n * 65:
        if recent_opp_c <= 3:
            return 'D' if rng.random() < 0.70 else 'C'
        if recent_opp_c >= 8:
            return 'C'

    return 'C'
